// --- PARAMETRI ---
float zoom = 1.0;       // Collegato alla densità/zoom dell'UI
int max_iter = 100;     // Qualità del dettaglio

// ESPONENTE della formula Z = Z^n + C (slider F), n = 1 + F.
// Con F = 1 (il valore di partenza degli slider) e' il Mandelbrot classico,
// n = 2. Alzando F cresce l'ordine di simmetria (n = 3: due lobi, n = 4: tre,
// ...) e i valori intermedi fondono con continuita' una forma nell'altra.
// Fra un intero e l'altro compare un taglio a sinistra, lungo il semiasse
// reale negativo: e' la potenza non intera di un numero complesso, non un
// errore, e sparisce di nuovo sul valore intero successivo.
// max(): sotto F = 1 resta il classico. Con n < 2 quel taglio domina la
// figura, che esce spostata e mozzata.
float power = 1.0 + max(F, 1.0);

// Centro del frattale: -0.5 e' l'inquadratura classica per n = 2; con
// esponenti piu' alti la figura si raccoglie attorno all'origine.
vec2 center = vec2(-0.5 / (power - 1.0), 0.0);

// --- MAPPATURA COORDINATE ---
// Trasformiamo u,v (0.0 - 1.0) nel piano complesso
// Moltiplichiamo per 3.0 per avere un'inquadratura iniziale classica.
// Dividiamo per 'zoom' per ingrandire.
vec2 c = (vec2(u, v) - 0.5) * (3.0 / zoom) + center;

// --- LOGICA MANDELBROT (Z = Z^n + C) ---
vec2 z = vec2(0.0);
int iter = 0;

for (int i = 0; i < 100; i++) { // Loop fisso per GLSL (usa max_iter per il break)
    if (i >= max_iter) break;

    // Ottimizzazione: se la distanza al quadrato > 4, è scappato
    // (raggio di fuga 2, valido per ogni n >= 2)
    if (dot(z, z) > 4.0) break;

    if (abs(power - 2.0) < 0.001) {
        // Caso classico, in aritmetica esatta e piu' veloce: (x + iy)^2 + c
        // Parte Reale: x^2 - y^2 + cx
        // Parte Immaginaria: 2xy + cy
        z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;
    } else {
        // Esponente qualsiasi, in forma polare: il modulo va alla n,
        // l'angolo si moltiplica per n. z = 0 (la prima iterazione) va
        // escluso: atan(0, 0) non e' definito su tutte le GPU.
        float r = length(z);
        vec2 zn = vec2(0.0);
        if (r > 0.0) {
            float ang = atan(z.y, z.x) * power;
            zn = pow(r, power) * vec2(cos(ang), sin(ang));
        }
        z = zn + c;
    }
    iter++;
}

// --- COLORAZIONE ---
// Normalizziamo le iterazioni tra 0.0 e 1.0
float tit = float(iter) / float(max_iter);

// Usiamo una radice quadrata (pow 0.5) per rendere il gradiente più visibile
// e meno "tutto nero" ai bordi.
tit = sqrt(tit);

// Mix tra i colori dell'utente
// tit=0 (esterno immediato) -> Colore 1
// tit=1 (interno insieme)   -> Colore 2
return mix(u_col1, u_col2, tit);
